select manageStatus from  reserverest where  onedayclass_num =#{onedayclass_num}
 AND openday >= STR_TO_DATE(#{openday}, '%Y-%m-%d')
      AND openday < DATE_ADD(STR_TO_DATE(#{openday}, '%Y-%m-%d'), INTERVAL 1 DAY)

SELECT *
FROM onedayclass AS o
INNER JOIN reserverest AS r
    ON o.onedayclass_num = r.onedayclass_num
WHERE o.teacher_id = #{teacher_id}
  AND r.openday BETWEEN #{selectOpenMinDate} AND #{selectOpenMaxDate} and r.manageStatus='open';

mapper.update:
UPDATE reserverest
SET manageStatus = #{manageStatus}
WHERE onedayclass_num = #{onedayclass_num}
  AND openday >= STR_TO_DATE(#{openday}, '%Y-%m-%d')
  AND openday < DATE_ADD(STR_TO_DATE(#{openday}, '%Y-%m-%d'), INTERVAL 1 DAY)
  AND manageStatus = #{nowStatus}
